    private static var cache: [Reicon: NSImage] = [:]

    var image: NSImage {
        if let cached = Self.cache[self] { return cached }
        let image = NSImage(data: Data(svg.utf8)) ?? NSImage(size: NSSize(width: 24, height: 24))
        image.isTemplate = true
        Self.cache[self] = image
        return image
    }

    func draw(in rect: NSRect, color: NSColor) {
        image.tinted(color).draw(in: rect, from: .zero, operation: .sourceOver, fraction: 1, respectFlipped: true, hints: [.interpolation: NSImageInterpolation.high])
    }
}

struct Icon: View {
    let icon: Reicon
    var size: CGFloat = 16

    init(_ icon: Reicon, size: CGFloat = 16) {
        self.icon = icon
        self.size = size
    }

    var body: some View {
        Image(nsImage: icon.image)
            .renderingMode(.template)
            .resizable()
            .interpolation(.high)
            .frame(width: size, height: size)
    }
}
